// ============================================================
//  Hyperspeed.jsx — Night Highway Effect
// ============================================================

import { useEffect, useRef } from 'react';

const Hyperspeed = ({ effectOptions = {} }) => {
  const containerRef = useRef(null);
  const hyperspeedRef = useRef(null);

  useEffect(() => {
    let hyperspeedInstance;

    const initHyperspeed = async () => {
      // Dynamic import to avoid bundling issues
      const { Hyperspeed: HyperspeedClass } = await import('hyperspeed');

      const defaultOptions = {
        distortion: 'turbulentDistortion',
        length: 400,
        roadWidth: 10,
        islandWidth: 2,
        lanesPerRoad: 3,
        fov: 90,
        fovSpeedUp: 150,
        speedUp: 2,
        carLightsFade: 0.4,
        totalSideLightSticks: 50,
        lightPairsPerRoadWay: 50,
        shoulderLinesWidthPercentage: 0.05,
        brokenLinesWidthPercentage: 0.1,
        brokenLinesLengthPercentage: 0.5,
        lightStickWidth: [0.12, 0.5],
        lightStickHeight: [1.3, 1.7],
        movingAwaySpeed: [60, 80],
        movingCloserSpeed: [-120, -160],
        carLightsLength: [400 * 0.05, 400 * 0.15],
        carLightsRadius: [0.05, 0.14],
        carWidthPercentage: [0.3, 0.5],
        carShiftX: [-0.2, 0.2],
        carFloorSeparation: [0.05, 1],
        colors: {
          roadColor: 0x080808,
          islandColor: 0x0a0a0a,
          background: 0x000000,
          shoulderLines: 0x131318,
          brokenLines: 0x131318,
          leftCars: [0xd856bf, 0x6750a2, 0xc247ac],
          rightCars: [0x03b3c3, 0x0e5ea5, 0x324555],
          sticks: 0x03b3c3,
        }
      };

      const options = { ...defaultOptions, ...effectOptions };

      hyperspeedInstance = new HyperspeedClass(containerRef.current, options);
      hyperspeedRef.current = hyperspeedInstance;
    };

    initHyperspeed();

    return () => {
      if (hyperspeedRef.current) {
        hyperspeedRef.current.destroy?.();
      }
    };
  }, [effectOptions]);

  return (
    <div 
      ref={containerRef} 
      className="hero__hyperspeed"
      style={{ width: '100%', height: '100%' }}
    />
  );
};

export default Hyperspeed;
